  PostProcessor post=(prefix,version)->new PostProcessor.Session(){public void seedAnchors(String key){assertThat(key).isEqualTo(tree.path("anchorsKey").asText());}public void split(String g,List<String> keys)throws Exception{split(g,keys,"",2);}public void split(String g,List<String> keys,String poses)throws Exception{split(g,keys,poses,2);}public void split(String g,List<String> keys,String poses,int layer)throws Exception{postCalls.incrementAndGet();assertThat(layer).isEqualTo(2);assertThat(keys).isEqualTo(CustomGridPrompt.SLOTS);for(String key:keys)storage.upload(prefix+"/"+key+".webp",fixture,"image/webp");}public void close()throws Exception{Path anchors=root.resolve("synthetic-anchors.json");Files.writeString(anchors,anchorsJson(scenario.equals("missing-anchor")).replace("\"w\":32",scenario.equals("canvas-mismatch")?"\"w\":31":"\"w\":32"));storage.upload(prefix+"/anchors.json",anchors,"application/json");}};
  var executor=new CustomGridGenerationExecutor(generator,post,storage,"v1",python);var worker=new BundleJobWorker(jdbc,transactions,attendance,plans,python,true);GenerationExecutor checked=new GenerationExecutor(){public void preflight()throws Exception{executor.preflight();}public String execute(CustomGenerationRequest request,Path out)throws Exception{String result=executor.execute(request,out);if(!failedOutput)return result;var manifest=mapper.readValue(result,BundleJobWorker.Manifest.class);var assets=new ArrayList<>(manifest.assets());var a=assets.get(0);assets.set(0,new BundleAssetVerifier.Input(a.motionOrder(),a.localFile(),a.assetKey(),"0".repeat(64),a.humanReview(),false));return mapper.writeValueAsString(new BundleJobWorker.Manifest(manifest.executionId(),assets,manifest.usedSources(),manifest.requestId(),manifest.pipelineVersion(),manifest.requestedQuality(),manifest.actualQuality(),manifest.provider(),manifest.model()));}};var service=new RealCustomBundleService(planning,worker,checked,author,"SYNTHETIC_TEXT_MODEL");if(failedOutput){assertThatThrownBy(()->service.run(job,"synthetic-one-run",root.resolve("job"),now)).hasMessage("One or more assets failed checks");assertThat(jdbc.queryForObject("select state from zzal_custom_bundle_source where job_id=?",String.class,job)).isEqualTo("RESERVED");assertThat(ownership.owned(owner,pet.getId())).isEmpty();assertThat(jdbc.queryForObject("select state from zzal_custom_bundle_job where id=?",String.class,job)).isEqualTo("FAILED");assertThat(authorCalls.get()).isEqualTo(1);assertThat(imageCalls.get()).isEqualTo(1);assertThat(postCalls.get()).isEqualTo(1);assertThat(service.run(job,"synthetic-retry",root.resolve("retry"),now)).isFalse();assertThat(authorCalls.get()).isEqualTo(1);assertThat(imageCalls.get()).isEqualTo(1);return;}assertThat(service.run(job,"synthetic-one-run",root.resolve("job"),now)).isTrue();
  assertThat(authorCalls.get()).isEqualTo(1);assertThat(imageCalls.get()).isEqualTo(1);assertThat(postCalls.get()).isEqualTo(1);assertThat(jdbc.queryForObject("select state from zzal_custom_bundle_job where id=?",String.class,job)).isEqualTo("GENERATED");assertThat(jdbc.queryForObject("select state from zzal_custom_bundle_source where job_id=?",String.class,job)).isEqualTo("USED");assertThat(jdbc.queryForObject("select count(*) from zzal_custom_bundle_asset where job_id=? and auto_check='PASS' and published=false and human_review='UNREVIEWED'",Integer.class,job)).isEqualTo(8);assertThat(ownership.owned(owner,pet.getId())).isEmpty();assertThat(jdbc.queryForObject("select snapshot_json from zzal_custom_bundle_job where id=?",String.class,job)).isEqualTo(snapshot);
  var rawManifest=mapper.readTree(Files.readString(root.resolve("job/manifest.json")));String prefix="images/zzal/custom/"+rawManifest.path("requestId").asText();
