  var downloads=new AtomicInteger();var stale=new java.util.concurrent.atomic.AtomicBoolean();S3Storage checkedStorage=new S3Storage(null,"synthetic-only"){@Override public void download(String key,Path target){assertThat(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()).isFalse();downloads.incrementAndGet();if(scenario.equals("missing-asset")&&key.endsWith("/"+CustomGridPrompt.SLOTS.getLast()+".webp"))throw new IllegalStateException("synthetic missing asset");storage.download(key,target);if(scenario.equals("stale")&&key.endsWith("/"+CustomGridPrompt.SLOTS.getLast()+".webp")&&stale.compareAndSet(false,true))jdbc.update("update zzal_custom_bundle_asset set human_review='REJECTED' where job_id=? and motion_order=1",job);}};
